//! A minimal re-implementation of the `tsl::hopscotch_map` interface used by
//! the test program, backed by the standard library hash map.
//!
//! Only the operations exercised by the test are provided: `insert`
//! (which does not overwrite an existing key), index-or-assign via
//! `insert_or_assign` (the `operator[]` + assignment idiom), and equality
//! comparison (element-wise, order-independent).

use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct HopscotchMap {
    inner: HashMap<i64, i64>,
}

impl HopscotchMap {
    pub fn new() -> Self {
        HopscotchMap {
            inner: HashMap::new(),
        }
    }

    /// Mirrors `std::map`-style `insert({k, v})`: no-op if the key exists.
    pub fn insert(&mut self, key: i64, value: i64) {
        self.inner.entry(key).or_insert(value);
    }

    /// Mirrors `map[key] = value`: inserts or overwrites.
    pub fn insert_or_assign(&mut self, key: i64, value: i64) {
        self.inner.insert(key, value);
    }
}

impl PartialEq for HopscotchMap {
    fn eq(&self, other: &Self) -> bool {
        self.inner == other.inner
    }
}

