//! Rust port of /workspace/dataset/hopscotch-map/tests/test14.cpp
//!
//! Builds two identical hopscotch maps, prints their equality, mutates one
//! via `map2[0] = 999`, and prints equality again. Output matches the C++
//! `std::cout << bool` formatting (`1`/`0`).

mod hopscotch_map;

use hopscotch_map::HopscotchMap;

/// Re-implements C++ `std::stoi` semantics for the cases this program can hit:
/// leading whitespace skipped, optional sign, leading digit run parsed,
/// trailing junk ignored. Panics (like C++ throws) on no digits or overflow.
fn stoi(s: &str) -> i64 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && bytes[i].is_ascii_whitespace() {
        i += 1;
    }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        neg = bytes[i] == b'-';
        i += 1;
    }
    let start = i;
    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val
            .checked_mul(10)
            .and_then(|v| v.checked_add((bytes[i] - b'0') as i64))
            .expect("stoi"); // std::out_of_range analog
        i += 1;
    }
    if i == start {
        panic!("stoi"); // std::invalid_argument analog
    }
    let val = if neg { -val } else { val };
    // C++ int parameter: stoi would throw on int overflow; keep within i32.
    assert!(val >= i32::MIN as i64 && val <= i32::MAX as i64, "stoi");
    val
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut count: i64 = 14;
    if args.len() > 1 && args[1] == "--a" {
        count = stoi(&args[2]);
    }

    let mut map1 = HopscotchMap::new();
    let mut map2 = HopscotchMap::new();

    for i in 0..count {
        map1.insert(i, i * 11);
        map2.insert(i, i * 11);
    }

    print!("{} ", if map1 == map2 { 1 } else { 0 });
    map2.insert_or_assign(0, 999);
    println!("{}", if map1 == map2 { 1 } else { 0 });
}

